package dev.jclawlor.FitnessGoals.entity;

import jakarta.persistence.*;
import lombok.Data;

@Entity
@Table(name = "lifting_exercises")
@Data
@SequenceGenerator(name = "lift_seq", sequenceName = "lifting_exercises_id_seq", allocationSize = 1)
public class LiftingExercise {

    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "lift_seq")
    private Long id;

    private String name;
    private int sets;
    private int reps;
    private double weight;

    public LiftingExercise() { }
    // getters/setters (Lombok @Data already generates them)
}
```

